import base64, hashlib, hmac, json
def b64(b): return base64.urlsafe_b64encode(b).rstrip(b"=").decode()
def ub64(s): return base64.urlsafe_b64decode(s + "=" * (-len(s) % 4))
KEY = b"demo-secret"
def mac(h, p): return b64(hmac.new(KEY, f"{h}.{p}".encode(), hashlib.sha256).digest())
def sign(payload, alg="HS256"):
    h = b64(json.dumps({"alg": alg, "typ": "JWT"}).encode())
    p = b64(json.dumps(payload).encode())
    return f"{h}.{p}.{mac(h, p) if alg == 'HS256' else ''}"
def verify(tok, aud, now):
    h, p, s = tok.split(".")
    if json.loads(ub64(h))["alg"] != "HS256":
        return "거부: alg"                      # 헤더가 말하는 alg 를 믿지 않는다
    if not hmac.compare_digest(s, mac(h, p)):
        return "거부: 서명"
    c = json.loads(ub64(p))
    if c["exp"] <= now:
        return "거부: 만료"
    if c["aud"] != aud:
        return "거부: 대상(aud)"
    return "통과: " + c["sub"]

now = 1_800_000_000
ok = sign({"sub": "user-1", "aud": "vehicle-api", "exp": now + 300})
print(verify(ok, "vehicle-api", now))        # 통과: user-1
print(verify(ok, "billing-api", now))
print(verify(ok, "vehicle-api", now + 301))
print(verify(sign({"sub": "admin", "aud": "vehicle-api", "exp": now + 300}, alg="none"), "vehicle-api", now))
h, p, s = ok.split(".")
forged = h + "." + b64(json.dumps({"sub": "admin", "aud": "vehicle-api", "exp": now + 300}).encode()) + "." + s
print(verify(forged, "vehicle-api", now))

ROLES = {"fleet-admin": {"vehicle:read", "vehicle:command"}, "viewer": {"vehicle:read"}}

def rbac(user, action):
    return any(action in ROLES[r] for r in user["roles"])

def abac(user, action, vehicle):
    if not rbac(user, action):
        return False
    same_org = user["org"] == vehicle["owner_org"]
    if action == "vehicle:command":
        return same_org and vehicle["speed_kmh"] == 0
    return same_org

kim = {"roles": ["fleet-admin"], "org": "A렌터카"}
print(rbac(kim, "vehicle:command"))                                          # True
print(abac(kim, "vehicle:command", {"owner_org": "A렌터카", "speed_kmh": 0}))   # True
print(abac(kim, "vehicle:command", {"owner_org": "B물류", "speed_kmh": 0}))     # False
print(abac(kim, "vehicle:command", {"owner_org": "A렌터카", "speed_kmh": 60}))  # False
